    // Editing person contact fields updates values and last edited date
    @Test
    public void test_edit_person_contact_fields() {
        Phonebook phonebook = new Phonebook(null);
        Person person = new Person("John", "Doe", "1234567890", "M", LocalDate.of(1990, 1, 1));
        phonebook.addContact(person);
    
        phonebook.editContact(0, "name", "Jane");
    
        Assertions.assertEquals("Jane", person.getName());
        Assertions.assertEquals(LocalDate.now(), person.getLastEditedDate());
    }

    // Editing organization contact fields updates values and last edited date
