        Phonebook phonebook = new Phonebook(null);
        Organization organization = new Organization("Tech Corp", "123 Tech Street", "0987654321");
        phonebook.addContact(organization);
    
        phonebook.editContact(0, "address", "456 New Tech Street");
    
        Assertions.assertEquals("456 New Tech Street", organization.getAddress());
